    fn default_process_lookup_finds_c_runtime_allocator_symbols() {
        assert!(lookup_process_native_symbol("malloc").is_some());
        assert!(lookup_process_native_symbol("free").is_some());
    }

    #[test]
    fn safe_native_call_roots_thrown_java_exception_until_router_consumes() {
        fn throwing_native(
            ctx: &mut dyn cratonvm_native_api::NativeContext,
            _args: &[Value],
        ) -> MethodCallResult {
            let stale = unsafe { ObjectRef::from_raw(0xfeed_face_0000_1000usize as *mut u8) };
            let live = ctx.alloc_object(ClassId::new(0), 0);
            ctx.pin_native_root(live);
            Err(MethodCallFailed::ExceptionThrown(stale))
        }

        let shared = test_shared();
        let mut thread = JvmThread::new(ThreadId(0), "test");
        let result = safe_native_call(&shared, &mut thread, throwing_native, &[]);
        let thrown = match result {
            Err(MethodCallFailed::ExceptionThrown(exc)) => exc,
            other => panic!("expected native Java exception, got {other:?}"),
        };
        assert_ne!(
            thrown.as_ptr() as usize,
            0xfeed_face_0000_1000usize,
            "stale native exception refs must be replaced from the handoff pin"
        );
        assert!(
            shared
                .mem
                .heap
                .is_object_address(thrown.as_ptr() as usize)
                .is_some(),
            "native exception handoff must resolve to a live heap object"
        );
        assert_eq!(
            thread.native_pending_return,
            Some(thrown),
            "native-thrown exception must stay rooted until the exception router consumes it"
        );
        assert_eq!(
            thread.native_pin_roots.len(),
            0,
            "safe_native_call still owns and releases native handoff pins"
        );
        assert!(
            thread.root_snapshot.lock().is_empty(),
            "a runnable native exception must defer snapshot publication until a collector-visible boundary"
        );

        crate::runtime::interpreter::update_root_snapshot(&shared, &mut thread);
        assert!(
            thread
                .root_snapshot
                .lock()
                .iter()
                .any(|root| root.as_ptr() == thrown.as_ptr()),
            "the next safepoint must publish the pending native exception"
        );
    }

    #[test]
    fn safe_native_object_return_is_published_at_the_next_safepoint() {
        fn object_native(
            ctx: &mut dyn cratonvm_native_api::NativeContext,
            _args: &[Value],
        ) -> MethodCallResult {
            Ok(Some(Value::Object(Some(
                ctx.alloc_object(ClassId::new(0), 0),
            ))))
        }

        let shared = test_shared();
        let mut thread = JvmThread::new(ThreadId(0), "test");
        let returned = match safe_native_call(&shared, &mut thread, object_native, &[])
            .expect("native return should succeed")
        {
            Some(Value::Object(Some(obj))) => obj,
            other => panic!("expected object native return, got {other:?}"),
        };
        assert_eq!(thread.native_pending_return, Some(returned));
        assert!(
            thread.root_snapshot.lock().is_empty(),
            "a runnable native return must defer snapshot publication until a collector-visible boundary"
        );

        crate::runtime::interpreter::update_root_snapshot(&shared, &mut thread);
        assert!(
            thread
                .root_snapshot
                .lock()
                .iter()
                .any(|root| root.as_ptr() == returned.as_ptr()),
            "the next safepoint must publish the pending native return"
        );
    }

    #[test]
    fn leaked_blocked_fixup_remaps_live_native_handle_slots() {
        let shared = test_shared();
        let mut thread = JvmThread::new(ThreadId(0), "handle-fixup-test");
        let before = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        let after = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        thread.handle_slots.push(Some(before));
        thread
            .gc_block_state
            .fixup
            .lock()
            .insert(before.as_ptr() as usize, after.as_ptr() as usize);

        assert_eq!(apply_pending_blocked_fixups(&shared, &mut thread), 1);
        assert_eq!(
            thread.handle_slots,
            vec![Some(after)],
            "safepoint repair must rewrite handle slots when blocked wake was skipped"
        );
    }

